llm.raw_content:
{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C09"],
      "claim": "Prochlorperazine, a phenothiazine with the same tricyclic core and propylamine side chain, has an absolute oral bioavailability of 5.7% in humans after a 5 mg oral tablet, well below the 20% threshold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Fluphenazine, a closely related trifluoromethyl phenothiazine with a piperazinylpropyl side chain, has a geometric mean absolute oral bioavailability of 2.7% in healthy volunteers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C20"],
      "claim": "Trifluoperazine, the N-methylpiperazinylpropyl phenothiazine analogue, shows small and erratic oral bioavailability (mean 6.0%, range 2–8%) in patients.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Levomepromazine, another phenothiazine, is reported to have absolute oral bioavailability of 30–70% in humans, above the threshold; this is contradictory but comes from a less similar analogue with different substituents.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C19"],
      "claim": "Pridopidine, a methylsulfonylphenyl piperidine without the phenothiazine core, has high oral availability in humans; this supports high bioavailability but transfers weakly to the tricyclic query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a phenothiazine-like tricyclic with a methylsulfonyl substituent and a piperidinecarboxamide propyl side chain. The closest experimental analogues—prochlorperazine, trifluoperazine, and fluphenazine—show absolute oral bioavailability of about 3–13%, all below 20%, strongly supporting a low prediction. Less similar methylsulfonylpiperidine or phenothiazine compounds with higher F are outweighed by the more direct phenothiazine evidence.",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "The effect of the methylsulfonyl and primary carboxamide groups on absorption and first-pass metabolism is inferred rather than measured.",
    "Contradictory high-F evidence comes from structurally less similar molecules with different side chains or cores."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

